import json
from collections import deque

def solve_bfs(map_id, start_x, start_y, target_x, target_y):
    # Standard dimensions
    # Vermilion City Map 0_5: 40 x 36
    # Cerulean City Map 0_3: 40 x 36
    # Pokémon Center Map 0_89: 14 x 8
    width, height = 40, 36
    if map_id == "0_89":
        width, height = 14, 8

    # Set up solids representation
    solids = set()

    # Generic inside structures for PC
    if map_id == "0_89":
        # Counters, chairs, desks
        for x in range(14):
            solids.add((x, 0))
            solids.add((x, 1))
            solids.add((x, 2)) # Counters
        solids.add((0, 3))
        solids.add((1, 3))
        solids.add((2, 3))
        solids.add((5, 3))
        solids.add((6, 3))
        solids.add((7, 3))
        solids.add((8, 3))
        solids.add((9, 3))
        solids.add((10, 3))
        solids.add((11, 3))
        solids.add((12, 3))
        solids.add((13, 3)) # PC Desk
        # Potted plants at bottom right
        solids.add((12, 6))
        solids.add((13, 6))
        solids.add((12, 7))
        solids.add((13, 7))
        # Known static NPCs
        solids.add((10, 5)) # Green-haired NPC
        solids.add((5, 4))  # Gentleman NPC
        solids.add((0, 4))  # Lass NPC

    elif map_id == "0_5": # Vermilion City
        # Major building bounding boxes
        # Pokémon Fan Club around (9, 13): (8, 12)-(10, 13) except door (9, 13)
        for x in range(8, 11):
            for y in range(10, 14):
                if (x, y) != (9, 13):
                    solids.add((x, y))
        # Fishing Guru House around (15, 13): (14, 12)-(16, 13) except door (15, 13)
        for x in range(14, 17):
            for y in range(10, 14):
                if (x, y) != (15, 13):
                    solids.add((x, y))
        # Pokémon Center around (11, 3): (10, 2)-(12, 3) except door (11, 3)
        for x in range(10, 13):
            for y in range(0, 4):
                if (x, y) != (11, 3):
                    solids.add((x, y))
        # Poké Mart around (23, 13): (22, 12)-(24, 13) except door (23, 13)
        for x in range(22, 25):
            for y in range(10, 14):
                if (x, y) != (23, 13):
                    solids.add((x, y))
        # Pidgey House around (23, 19): (22, 18)-(24, 19) except door (23, 19)
        for x in range(22, 25):
            for y in range(18, 20):
                if (x, y) != (23, 19):
                    solids.add((x, y))
        # Gym around (11, 31): (10, 30)-(12, 31) except door (11, 31)
        for x in range(10, 13):
            for y in range(30, 32):
                if (x, y) != (11, 31):
                    solids.add((x, y))
        # Diglett's Cave building around (34, 13): (33, 12)-(35, 13) except door (34, 13)
        for x in range(33, 36):
            for y in range(11, 14):
                if (x, y) != (34, 13):
                    solids.add((x, y))

        # Water Channels (TYPE_4e8c)
        for x in range(0, 10):
            for y in range(6, 9):
                solids.add((x, y))
        for x in range(10, 15):
            for y in range(8, 9):
                solids.add((x, y))
        for x in range(6, 10):
            for y in range(16, 21):
                solids.add((x, y))
        # Southern pier boundaries / Water at bottom
        for x in range(40):
            for y in range(28, 36):
                # Only let Column 30 be passable below Row 28
                if x != 30:
                    solids.add((x, y))

        # Row 13 fence posts:
        # Fences and blockages on Row 13 / 19 / 20 / 25
        # The fence on Row 13 from Column 20 to 29 is solid
        for x in range(20, 30):
            solids.add((x, 13))
        # Obstacles blocking Column 6 and 7 at Row 19 (fence posts/mailbox)
        solids.add((6, 19))
        solids.add((7, 19))

        # Snorlax blockage at (34, 13) and (35, 13)
        solids.add((34, 13))
        solids.add((35, 13))

    elif map_id == "0_3": # Cerulean City
        # Major buildings and fences
        # Row 28 Tree Barrier Columns 21 to 35
        for x in range(21, 36):
            solids.add((x, 28))
        # Row 33 barrier Columns 32 to 38
        for x in range(32, 39):
            solids.add((x, 33))
        # Column 35 fence Rows 20 to 27
        for y in range(20, 28):
            solids.add((35, y))
        # Column 38 wall Rows 19 to 33
        for y in range(19, 34):
            solids.add((38, y))

    # BFS pathfinder
    queue = deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    while queue:
        x, y, path = queue.popleft()
        if (x, y) == (target_x, target_y):
            return path

        for dx, dy, move in [(0, -1, 'Up'), (0, 1, 'Down'), (-1, 0, 'Left'), (1, 0, 'Right')]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < width and 0 <= ny < height:
                # Collision checks
                if (nx, ny) in solids:
                    continue
                # Route 25 north ledges exception
                if map_id == "0_25" and ny == 6 and move == 'Up' and nx != 9:
                    continue
                # S.S. Anne deck ledges etc. can be handled if needed

                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, path + [move]))

    return []

print(json.dumps(solve_bfs(input_data['map_id'], input_data['start_x'], input_data['start_y'], input_data['target_x'], input_data['target_y'])))
